import knex from 'knex';
import 'dotenv/config';

// One instance for the whole app. Routers import this object.
export const db = knex({
    client: 'mysql2',
    connection: {
        host: process.env.DB_HOST || '127.0.0.1',
        user: process.env.DB_USER || 'root',
        password: process.env.DB_PASSWORD || '',
        database: process.env.DB_NAME || 'bookings',
        // DATE columns stay as "2026-07-01" strings.
        dateStrings: true,
    },
    pool: { min: 0, max: 10 },
});

// GET /api/hotels
const rows = await db('hotels')
    .select('id', 'city', 'name', 'stars')
    .orderBy('name', 'asc');

// Same query with aliases, used when two tables share a column name.
const joined = await db('hotels as h')
    .select({
        hotel_id: 'h.id',
        hotel_name: 'h.name',
        owner_email: 'h.owner_email',
    });

response.json(rows);

// GET /api/hotels?city=Eger&min_stars=3
const query = db('hotels').select('id', 'name', 'city', 'stars');

if (city) query.where('city', city);
if (minStars > 0) query.where('stars', '>=', minStars);

// Object form, all conditions joined with AND.
const booking = await db('bookings')
    .where({ customer_email: email, hotel_id: hotelId })
    .first();

// Callback form keeps the ORs together: (city OR name) AND stars >= 3.
const results = await db('hotels')
    .where((group) => {
        group.where('city', 'like', '%Eger%').orWhere('name', 'like', '%Eger%');
    })
    .where('stars', '>=', 3);

// Hotels with the owner name, plus a booking count that can be zero.
const rows = await db('hotels as h')
    .join('customers as c', 'c.email', 'h.owner_email')
    .leftJoin('bookings as b', 'b.hotel_id', 'h.id')
    .select(
        'h.id',
        'h.name',
        db.raw("CONCAT(c.first_name, ' ', c.last_name) AS owner_name"),
        // COUNT of a joined column, not COUNT(*): the empty hotel has one
        // row of nulls and COUNT(*) would report 1.
        db.raw('COUNT(b.customer_email) AS bookings')
    )
    .groupBy('h.id', 'h.name', 'c.first_name', 'c.last_name')
    .orderBy('h.name', 'asc');

// POST /api/hotels
const row = {
    city: 'Pecs',
    name: 'Zsolnay Udvar',
    description: 'Rooms above the old factory.',
    stars: 4,
    owner_email: 'kovacs.anna@example.test',
};

const [id] = await db('hotels').insert(row);
response.status(201).json({ id, ...row });

// An array inserts several rows in one statement and returns the first id.
await db('customers').insert([
    { email: 'a@example.test', first_name: 'Anna', last_name: 'Kovacs', phone: '' },
    { email: 'b@example.test', first_name: 'Bela', last_name: 'Nagy', phone: '' },
]);

// PUT /api/booking, partial update
// Only fields the client sent are written.
const patch = {};
for (const field of ['start_date', 'end_date', 'adults', 'children']) {
    if (Object.hasOwn(request.body, field)) patch[field] = request.body[field];
}

if (Object.keys(patch).length === 0) {
    throw new HttpError(400, 'Send at least one field to update');
}

const affected = await db('bookings')
    .where({ customer_email: email, hotel_id: hotelId })
    .update(patch);

if (affected === 0) {
    throw new HttpError(404, 'Booking not found');
}

